local k={136,100,150,101,158,117,73,34,189,226,139,6,97,139,194,3,80,84,210,139,123,120,129,206,15,119,232,118,90,35,202,167}
local s=[[]]
local t={}
local n=0
for i=1,#s,2 do
	n=n+1
	local v=tonumber(s:sub(i,i+1),16)
	t[n]=string.char(bit32.bxor(v,k[((n-1)%#k)+1]))
end
